object CatalogsItemValidationWarningsData {

  def validated(d8a : CatalogsItemValidationWarningsData, failFast : Boolean) : scala.util.Try[CatalogsItemValidationWarnings] = d8a.validated(failFast)

  def fromJson(jason : ujson.Value) : CatalogsItemValidationWarningsData = try {
        val data = read[CatalogsItemValidationWarningsData](jason)
        data
    } catch {
      case NonFatal(e) => sys.error(s"Error creating CatalogsItemValidationWarningsData from json '$jason': $e")
  }

  def fromJsonString(jason : String) : CatalogsItemValidationWarningsData = {
        val parsed = try {
           read[ujson.Value](jason)
        } catch {
          case NonFatal(e) => sys.error(s"Error parsing json '$jason': $e")
        }
        fromJson(parsed)
  }

  def manyFromJsonString(jason : String) : Seq[CatalogsItemValidationWarningsData] = try {
        read[List[CatalogsItemValidationWarningsData]](jason)
    } catch {
        case NonFatal(e) => sys.error(s"Error parsing json '$jason' as list: $e")
    }

  def manyFromJsonStringValidated(jason : String, failFast : Boolean = false) : Try[Seq[CatalogsItemValidationWarnings]] = {
      Try(manyFromJsonString(jason)).flatMap { list =>
        list.zipWithIndex.foldLeft(Try(Vector[CatalogsItemValidationWarnings]())) {
          case (Success(list), (next, i)) => 
            next.validated(failFast) match {
              case Success(ok) => Success(list :+ ok)
              case Failure(err) => Failure(new Exception(s"Validation error on element $i: ${err.getMessage}", err))
            }
          case (fail, _)  => fail
        }
      }
    }

  def mapFromJsonString(jason : String) : Map[String, CatalogsItemValidationWarningsData] = try {
        read[Map[String, CatalogsItemValidationWarningsData]](jason)
    } catch {
        case NonFatal(e) => sys.error(s"Error parsing json '$jason' as map: $e")
    }


  def mapFromJsonStringValidated(jason : String, failFast : Boolean = false) : Try[Map[String, CatalogsItemValidationWarnings]] = {
     Try(mapFromJsonString(jason)).flatMap { map =>
       map.foldLeft(Try(Map[String, CatalogsItemValidationWarnings]())) {
         case (Success(map), (key, next)) =>
           next.validated(failFast) match {
             case Success(ok) => Success(map.updated(key, ok))
             case Failure(err) => Failure(new Exception(s"Validation error on element $key: ${err.getMessage}", err))
